package com.yeyamo_mobile.api.notification_service.infrastructure.web;
import java.util.UUID;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import com.yeyamo_mobile.api.notification_service.application.*;import com.yeyamo_mobile.api.notification_service.domain.*;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;
@RestController@RequestMapping("/api/v1/notifications")public class NotificationController{private final NotificationApplicationService service;private final DevicePushTokenService devices;public NotificationController(NotificationApplicationService s,DevicePushTokenService d){service=s;devices=d;}@GetMapping@Operation(summary="List my notifications",security=@SecurityRequirement(name="bearerAuth"))public NotificationSlice mine(Authentication auth,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.mine(auth.getName(),page,size);}@GetMapping("/unread")public NotificationSlice unread(Authentication auth,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.unread(auth.getName(),page,size);}@GetMapping("/unread/count")public UnreadCountResponse unreadCount(Authentication auth){return new UnreadCountResponse(service.unreadCount(auth.getName()));}@PostMapping("/{id}/read")public Notification read(Authentication auth,@PathVariable UUID id){return service.read(auth.getName(),id);}@PostMapping("/read-all")public ReadAllResponse readAll(Authentication auth){return new ReadAllResponse(service.readAll(auth.getName()));}@DeleteMapping("/{id}")@ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT)public void delete(Authentication auth,@PathVariable UUID id){service.delete(auth.getName(),id);}@GetMapping("/preferences")public NotificationPreference preferences(Authentication auth){return service.preferences(auth.getName());}@PutMapping("/preferences")public NotificationPreference preferences(Authentication auth,@Valid@RequestBody PreferenceRequest r){return service.updatePreferences(auth.getName(),r.inAppEnabled(),r.emailEnabled(),r.pushEnabled(),r.emailAddress(),r.pushToken(),r.locale());}@PostMapping("/devices/push-token")public void registerPushToken(Authentication auth,@Valid@RequestBody PushTokenRequest r){devices.register(auth.getName(),r.token(),r.platform(),r.deviceId(),r.appVersion());}@DeleteMapping("/devices/push-token/{deviceId}")@ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT)public void unregisterPushToken(Authentication auth,@PathVariable String deviceId){devices.unregister(auth.getName(),deviceId);}public record PreferenceRequest(boolean inAppEnabled,boolean emailEnabled,boolean pushEnabled,@Email String emailAddress,@Size(max=500)String pushToken,@Pattern(regexp="[a-zA-Z]{2}([_-][a-zA-Z]{2})?")String locale){}public record PushTokenRequest(@NotBlank@Size(max=500)String token,@NotNull DevicePlatform platform,@NotBlank@Size(max=120)String deviceId,@Size(max=50)String appVersion){}public record ReadAllResponse(int updated){}public record UnreadCountResponse(long count){}}
